#include "../../Task_07/Task07_Morse_Playlist/Task07_Morse_Playlist.ino"
int main(){setup();sendAt(10,"0,2,1,2");runUntil(17000);require(!playing,"playlist finishes");auto first=Serial.output;require(first.find("binOutSeq0")<first.find("binOutSeq2")&&first.find("binOutSeq2")<first.find("binOutSeq1"),"playlist order");require(occurrences(first,"binOutSeq2")==2,"duplicate sequences preserved");sendAt(18000,"1,2,-1,0");runUntil(34000);require(!playing,"pause playlist finishes");require(Serial.output.find("LED OFF for 2000ms")!=std::string::npos,"explicit pause2000");require(binOutSeq0.seq[0].first==600&&binOutSeq0.seq[2].first==200&&binOutSeq0.seq[4].first==200&&binOutSeq0.seq[6].first==600,"X Morse dash dot dot dash");sendAt(35000,"0,3,1,2");require(!playing,"invalid playlist rejected");
std::cout<<"PASS Task 7\n";}
